using System.Diagnostics;
using System.IO;
using System.Text.Json;
using VisionFramework;
using VisionPluginContracts;

namespace VisionPlugins.Calibration;

public sealed partial class ReadCalibFilePlugin:IVisionToolPlugin,IWpfToolEditorFactory,IToolAssetPersistence,IToolNodeDescriptorProvider,IToolDisplayProvider {
 public const string Id="vision.read-calib-file";
 public ToolManifest Manifest{get;}=new(Id,"1.0.0","标定加载","calibration","catalog/ReadCalibFileModuImageEnable.png");
 public ToolDisplayDefinition DisplayDefinition{get;}=new("Module Status:{0}",["ModuStatus"],[]){TextVisible=false,ImageVisible=false,RecordVisible=true,ResultListVisible=false};
 public static readonly string[] PoseInputs=["SnapImagePointX1","SnapImagePointY1","SnapImageR1","SnapWorldPointX1","SnapWorldPointY1","SnapWorldR1","TeachWorldPointX1","TeachWorldPointY1","TeachWorldR1"];
 static readonly PortDescriptor[] Outputs=new[]{new PortDescriptor("ModuRunTime",DataKind.Number,false),new("ModuStatus",DataKind.Integer,false),new("RotDirectionState",DataKind.Integer,false),new("IsRightCoorA",DataKind.Integer,false),new("CalibMatrix",DataKind.NumberArray,false),new("CalibData",DataKind.Calibration,false)}.Concat(new[]{"RotCenterImage","RotCenterWorld","SnapImage","SnapWorld","TeachWorld","SnapWorldCur","SnapWorldObj"}.SelectMany(n=>new[]{n+"PointX",n+"PointY",n+"R"}).Select(n=>new PortDescriptor(n,DataKind.Number,false))).ToArray();
 public ModuleDescriptor Descriptor{get;}=new(Id,"1.0.0","标定加载",new[]{new PortDescriptor("RefreshSignal",DataKind.Integer,false)}.Concat(PoseInputs.Select(n=>new PortDescriptor(n,DataKind.Number,false))).ToArray(),Outputs,new[]{new ParameterDescriptor("FilePath",ParameterKind.Text,true,JsonSerializer.SerializeToElement("")),new("SaveCalibDataEnable",ParameterKind.Boolean,true,JsonSerializer.SerializeToElement(true)),new("CachedFileData",ParameterKind.Text,true,JsonSerializer.SerializeToElement("")),new("OutputSchema",ParameterKind.Text,true,JsonSerializer.SerializeToElement("[]")),new("ConfigurationUserData",ParameterKind.Text,true,JsonSerializer.SerializeToElement("{}")),new("DynamicInData",ParameterKind.Text,true,JsonSerializer.SerializeToElement("")),new("DynamicOutData",ParameterKind.Text,true,JsonSerializer.SerializeToElement(""))});
 public static string Schema(ReadCalibFileData data)=>JsonSerializer.Serialize(data.Ports());
 public ModuleDescriptor DescribeNode(NodeDocument node){var ports=Outputs.ToDictionary(p=>p.Name,StringComparer.Ordinal);foreach(var p in ReadSchema(node.Parameters)){if(p.Kind is not(DataKind.Number or DataKind.Integer or DataKind.Text or DataKind.NumberArray))throw new InvalidDataException("不支持的标定输出类型。");if(ports.TryGetValue(p.Name,out var existing)&&existing.Kind!=p.Kind)throw new InvalidDataException("标定文件输出与内置端口类型冲突："+p.Name);ports[p.Name]=new(p.Name,p.Kind,false);}var inputs=Descriptor.Inputs.ToDictionary(p=>p.Name,StringComparer.Ordinal);foreach(var extra in Extra(node.Parameters)){if(inputs.TryGetValue(extra.Name,out var input)&&input.Kind!=extra.Kind||ports.TryGetValue(extra.Name,out var existing)&&existing.Kind!=extra.Kind)throw new InvalidDataException("结果展示端口类型冲突："+extra.Name);inputs[extra.Name]=new(extra.Name,extra.Kind,false,AcceptInteger:extra.Type=="float");ports[extra.Name]=new(extra.Name,extra.Kind,false);}return Descriptor with{Inputs=inputs.Values.ToArray(),Outputs=ports.Values.ToArray()};}
 static IReadOnlyList<ReadCalibFileExtra> Extra(IReadOnlyDictionary<string,JsonElement> values){try{return ReadCalibFileExtra.Parse(values.TryGetValue("DynamicOutData",out var xml)?xml.GetString()??"":"");}catch(InvalidOperationException e){throw new InvalidDataException("额外结果展示定义必须为文本。",e);}}
 static ReadCalibFilePort[] ReadSchema(IReadOnlyDictionary<string,JsonElement> values){try{string json=values.TryGetValue("OutputSchema",out var value)?value.GetString()??"[]":"[]";var ports=JsonSerializer.Deserialize<ReadCalibFilePort[]>(json)??[];if(ports.Any(p=>p is null||string.IsNullOrWhiteSpace(p.Name))||ports.Select(p=>p.Name).Distinct(StringComparer.Ordinal).Count()!=ports.Length)throw new InvalidDataException("标定文件输出定义无效。");return ports;}catch(Exception e)when(e is JsonException or InvalidOperationException or NotSupportedException){throw new InvalidDataException("标定文件输出定义无法解析。",e);}}
 sealed class State {internal readonly object Gate=new();internal bool Initialized;internal string Requested="",Path="",Cache="";internal ReadCalibFileData Data=new();internal uint LoadError;internal IReadOnlyDictionary<string,PortValue>? LastInputs,LastOutputs;}
 readonly Dictionary<string,State> states=new();readonly object gate=new();
 State GetState(string node,string directory,ModuleExecutionScope? scope){if(scope is not null)return scope.State(Id,node,()=>new State());lock(gate){string key=System.IO.Path.GetFullPath(directory)+"|"+node;if(!states.TryGetValue(key,out var state))states[key]=state=new();return state;}}
 static void Apply(State state,ReadCalibFileLoad load,string path,bool disk){state.LoadError=load.ErrorCode;if(load.ReplaceData&&load.Data is {} data)state.Data=data;if(load.CommitPath){if(disk)state.Path=path;state.Cache=load.Data!.Xml;}}
 static void Configure(State state,IReadOnlyDictionary<string,JsonElement> values,string directory){string requested=values["FilePath"].GetString()??"";if(state.Initialized&&state.Requested==requested)return;bool first=!state.Initialized;state.Initialized=true;state.Requested=requested;if(first&&values.TryGetValue("CachedFileData",out var cached)&&!string.IsNullOrEmpty(cached.GetString())){state.Path=requested.Length==0?"":System.IO.Path.GetFullPath(requested,directory);Apply(state,ReadCalibFileData.Parse(cached.GetString()!),state.Path,false);}else if(requested.Length==0){state.Path=state.Cache="";state.Data=new();state.LoadError=0;}else{string path=System.IO.Path.GetFullPath(requested,directory);Apply(state,ReadCalibFileData.Read(path),path,true);}}
 public ReadCalibFileLoad Load(ToolEditorContext context,string path){var state=GetState(context.Node.Id,context.BaseDirectory,context.Scope);lock(state.Gate){state.Initialized=true;state.Requested=path;if(path.Length==0){state.Path=state.Cache="";state.Data=new();state.LoadError=0;return new(0,state.Data,true,true);}string full=System.IO.Path.GetFullPath(path,context.BaseDirectory);var load=ReadCalibFileData.Read(full);Apply(state,load,full,true);return load;}}
 public (ReadCalibFileData Data,uint Error) Snapshot(ToolEditorContext context){var state=GetState(context.Node.Id,context.BaseDirectory,context.Scope);lock(state.Gate){Configure(state,context.Node.Parameters,context.BaseDirectory);return(state.Data,state.LoadError);}}
 public ToolAssetSnapshot PrepareSave(NodeDocument node,string directory,ResourceCatalog resources)=>Save(node,directory,resources,null);
 public ToolAssetSnapshot PrepareSave(NodeDocument node,string directory,ResourceCatalog resources,ModuleExecutionScope? scope)=>Save(node,directory,resources,scope);
 ToolAssetSnapshot Save(NodeDocument node,string directory,ResourceCatalog resources,ModuleExecutionScope? scope){var state=GetState(node.Id,directory,scope);lock(state.Gate){Configure(state,node.Parameters,directory);var values=node.Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());values["CachedFileData"]=JsonSerializer.SerializeToElement(values["SaveCalibDataEnable"].GetBoolean()?state.Cache:"");return new(node with{Parameters=values},[]);}}
 public void Reset(string nodeId){lock(gate)foreach(string key in states.Keys.Where(k=>k.EndsWith("|"+nodeId,StringComparison.Ordinal)).ToArray())states.Remove(key);}
 public ToolDisplayFrame? LastDisplay(NodeDocument node,string baseDirectory,ModuleExecutionScope? scope){var state=GetState(node.Id,baseDirectory,scope);lock(state.Gate)return state.LastInputs is not null&&state.LastOutputs is not null?ToolDisplayService.Build(DisplayDefinition,ToolDisplayService.Read(node.Parameters,DisplayDefinition),state.LastInputs,state.LastOutputs):null;}
 public IModule CreateRuntime()=>new Runtime(this);
 public System.Windows.Forms.Form CreateEditor(ToolEditorContext context)=>throw new InvalidOperationException("Use WPF editor factory.");
 public System.Windows.Window CreateWpfEditor(ToolEditorContext context)=>new ReadCalibFileWindow(context,this);
 sealed class Runtime(ReadCalibFilePlugin owner):IModule {
  public ModuleDescriptor Descriptor=>owner.Descriptor;
  public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext c,CancellationToken cancellationToken){cancellationToken.ThrowIfCancellationRequested();var watch=Stopwatch.StartNew();var state=owner.GetState(c.NodeId,c.BaseDirectory,c.Scope);lock(state.Gate){
   Configure(state,c.Parameters,c.BaseDirectory);
   if(c.Inputs.TryGetValue("RefreshSignal",out var signal)&&signal.As<long>()!=0&&state.Path.Length>0)Apply(state,ReadCalibFileData.Read(state.Path),state.Path,true);
   Dictionary<string,PortValue> output;try{output=state.Data.Values().ToDictionary(p=>p.Key,p=>p.Value);}catch(ArgumentException){return ValueTask.FromResult(new ModuleResult(ModuleStatus.Failed,new Dictionary<string,PortValue>(),"INVALID_CALIBRATION_NUMBER","标定文件包含不能发布的非有限数值。"));}
   var node=new NodeDocument(c.NodeId,Id,"1.0.0","标定加载",c.Parameters.ToDictionary(p=>p.Key,p=>p.Value));var allowed=owner.DescribeNode(node).Outputs.ToDictionary(p=>p.Name,p=>p.Kind);
   if(output.Any(p=>!allowed.TryGetValue(p.Key,out var kind)||kind!=p.Value.Kind))return ValueTask.FromResult(new ModuleResult(ModuleStatus.Failed,new Dictionary<string,PortValue>(),"CALIBRATION_SCHEMA_CHANGED","标定文件输出已变化，请打开配置重新读取并确认。"));
   foreach(string name in PoseInputs)if(c.Inputs.TryGetValue(name,out var value)){double? number=value.Kind==DataKind.Number?value.As<double>():value.Kind==DataKind.NumberArray&&value.As<IReadOnlyList<double>>().Count>0?value.As<IReadOnlyList<double>>()[0]:null;if(number is {} v)output[name[..^1]]=PortValue.Number((float)v);}
   output["ModuStatus"]=PortValue.Integer(state.Data.Outputs.Count>0?1:0);try{foreach(var extra in Extra(c.Parameters))extra.Copy(c.Inputs,output);}catch(ArgumentException){return ValueTask.FromResult(new ModuleResult(ModuleStatus.Failed,new Dictionary<string,PortValue>(),"INVALID_CALIBRATION_NUMBER","结果展示包含不能发布的非有限数值。"));}output["ModuRunTime"]=PortValue.Number(watch.Elapsed.TotalMilliseconds);
   if(output.TryGetValue("CalibMatrix",out var matrix)&&matrix.Kind==DataKind.NumberArray&&matrix.As<IReadOnlyList<double>>().Count==9)output["CalibData"]=PortValue.Calibration(new CalibrationData(matrix.As<IReadOnlyList<double>>(),state.Path));
   state.LastInputs=c.Inputs.ToDictionary(p=>p.Key,p=>p.Value);state.LastOutputs=output.ToDictionary(p=>p.Key,p=>p.Value);return ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,output){NativeErrorCode=0});
  }}
 }
}
